const aiItems = $input.all();
const originalItems = $items("Extract Instagram Post Data");

return aiItems.map((item, i) => {

  const aiText =
    item.json?.content?.parts?.[0]?.text ||
    "{}";

  const clean = aiText
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(clean);
  } catch (e) {
    parsed = {
      is_event: null,
      parse_error: true,
      parse_error_message: e.message,
      raw_ai_response: aiText
    };
  }

  const orig = originalItems[i]?.json || {};

  return {
    json: {
      // ...orig,
      ...parsed

      // Keep original Instagram data
      // instagram_link:
      //   parsed.instagram_link ||
      //   orig.permalink ||
      //   null,

      // cover_image_url:
      //   // parsed.cover_image_url ||
      //   // orig.image_url ||
        // null
    }
  };
});

// Get all event candidates from the AI parsing node
const allEvents = $('Parse AI Response Node')
  .all()
  .map(item => item.json)
  .filter(event => event.is_event === true);

// Get the events that passed the duplicate filter
const newEvents = $('Filter New Instagram Events')
  .all()
  .map(item => item.json)
  .filter(event => event.is_event === true);

// Calculate counts
const totalEvents = allEvents.length;
const newEventCount = newEvents.length;
const duplicatesSkipped = totalEvents - newEventCount;

// Return a friendly status
return [
  {
    json: {
      status: 'SUCCESS',
      total_event_candidates: totalEvents,
      new_events: newEventCount,
      duplicates_skipped: duplicatesSkipped,
      document_created: true,
      message: `Import completed successfully. ${newEventCount} new event(s) added and ${duplicatesSkipped} duplicate(s) skipped.`
    }
  }
];

