// Get all event data from the AI parsing node
const events = $('Parse AI Response Node')
  .all()
  .map(item => item.json)
  .filter(event => event.is_event === true);

if (events.length === 0) {
  return [];
}

const now = new Date();

const date = now.toLocaleDateString('en-GB', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric'
});

const time = now.toLocaleTimeString('en-GB', {
  hour: '2-digit',
  minute: '2-digit'
});

const docTitle = `KYNCT Event Import - ${date} ${time}`;

function value(v, fallback = 'Not specified') {
  if (v === null || v === undefined || v === '') {
    return fallback;
  }

  return String(v);
}

function formatDateTime(event) {
  let result = value(event.start_date);

  if (event.start_time) {
    result += ` at ${event.start_time}`;
  }

  if (event.end_time) {
    const endDate = event.end_date || event.start_date;
    result += ` - ${value(endDate)} at ${event.end_time}`;
  }

  return result;
}

// Create event sections
const eventSections = events.map((event, index) => {

  const confidenceFlags =
    Array.isArray(event.confidence_flags)
      ? event.confidence_flags
      : [];

  const confidenceText =
    confidenceFlags.length > 0
      ? confidenceFlags.join(', ')
      : 'None';

  return `
EVENT ${index + 1}
========================================

COVER IMAGE

TITLE
${value(event.title)}

CATEGORY
${value(event.category)}

DATE & TIME
${formatDateTime(event)}

LOCATION NAME
${value(event.location_name)}

LOCATION ADDRESS
${value(event.location_address)}

DESCRIPTION
${value(event.description)}

SOCIAL IMPACT
Level: ${value(event.social_impact?.level, 'Unknown')}
Reason: ${value(event.social_impact?.reason, 'Not specified')}

TICKET LINK
${value(event.ticket_link)}

SOURCE URL
${value(event.source_url)}

SOURCE ID
${value(event.source_id)}

CONFIDENCE FLAGS
${confidenceText}

MAX ATTENDEES
${value(event.max_attendees)}

SAFETY POLICY FLAGS
${
  Array.isArray(event.safety_policy_flags)
    ? (
        event.safety_policy_flags.length > 0
          ? event.safety_policy_flags.join(', ')
          : 'None'
      )
    : 'None'
}

SAFETY RISK LEVEL
${value(event.safety_risk_level)}

SAFETY REVIEW REASON
${value(event.safety_review_reason)}


`;
}).join('\n');

const docBody = `
KYNCT — INSTAGRAM EVENT IMPORT
========================================

Import Date: ${date}
Import Time: ${time}
Total Events: ${events.length}

These events were automatically extracted from
Instagram posts and are ready for human review.

${eventSections}

========================================
END OF IMPORT
========================================
`;

// Find the image insertion position for EVERY event
const imageData = events
  .map((event, index) => {

    const eventMarker = `EVENT ${index + 1}`;
    const eventStart = docBody.indexOf(eventMarker);

    if (eventStart === -1 || !event.cover_image) {
      return null;
    }

    const coverImagePosition = docBody.indexOf(
      'TITLE',
      eventStart
    );

    if (coverImagePosition === -1) {
      return null;
    }

    return {
      url: event.cover_image,
      index: coverImagePosition + 1
    };
  })
  .filter(Boolean);

// IMPORTANT:
// Insert images from bottom to top so earlier indexes
// do not change when later images are inserted.
imageData.sort((a, b) => b.index - a.index);

// Build Google Docs image requests
const imageRequests = [];

for (const image of imageData) {

  imageRequests.push({
    insertInlineImage: {
      location: {
        index: image.index
      },
      uri: image.url,
      objectSize: {
        width: {
          magnitude: 220,
          unit: 'PT'
        }
      }
    }
  });

  imageRequests.push({
    insertText: {
      location: {
        index: image.index + 1
      },
      text: '\n'
    }
  });
}

return [
  {
    json: {
      doc_title: docTitle,
      event_count: events.length,
      doc_body: docBody,
      image_requests: imageRequests
    }
  }
];

const items = $input.all();

return items.map(item => {
  const json = item.json;

  // Existing content extraction
  const content =
    json.content ||
    json['content:encoded'] ||
    json.description ||
    '';

  // Existing: extract image URL from RSS HTML
  const imgMatch = content.match(/<img[^>]+src=["']([^"']+)["']/i);

  // New: support RSS enclosure / media image URLs
  const imageUrl =
    (imgMatch && imgMatch[1]) ||
    json.enclosure?.url ||
    json['media:content']?.url ||
    json.media?.content?.url ||
    json['media:thumbnail']?.url ||
    json.media?.thumbnail?.url ||
    null;

  // Caption extraction
  const caption =
    json.contentSnippet ||
    json.content ||
    json['content:encoded'] ||
    json.description ||
    '';

  return {
    json: {
      caption: caption,

      image_url: imageUrl,

      permalink:
        json.link ||
        null,

      timestamp:
        json.isoDate ||
        json.pubDate ||
        null,

      // Instagram profile username from RSS.app
      instagram_username:
        json.creator ||
        json['dc:creator'] ||
        null,

      source: 'instagram'
    }
  };
});

// Get all rows already stored in Google Sheets
const existingRows = $('Check Duplicate').all();

// Build existing dedupe keys using source_url + source_id
const existingKeys = new Set(
  existingRows
    .map(item => {
      const sourceUrl = item.json.source_url || '';
      const sourceId = item.json.source_id || '';

      if (!sourceUrl || !sourceId) {
        return null;
      }

      return `${sourceUrl}||${sourceId}`;
    })
    .filter(Boolean)
);

// Get all posts from Extract Instagram Post Data
const posts = $('Extract Instagram Post Data')
  .all()
  .map(item => item.json);

// Keep only posts that are not already in Google Sheets
const newPosts = posts.filter(post => {

  const sourceUrl =
    post.source_url ||
    post.permalink ||
    '';

  // Extract Instagram shortcode from the post URL
  const match = sourceUrl.match(
    /\/(?:p|reel|tv)\/([^/?]+)/i
  );

  const sourceId =
    post.source_id ||
    (match ? match[1] : '');

  if (!sourceUrl || !sourceId) {
    return false;
  }

  const dedupeKey = `${sourceUrl}||${sourceId}`;

  return !existingKeys.has(dedupeKey);
});

// Return only new posts
return newPosts.map(post => {

  const sourceUrl =
    post.source_url ||
    post.permalink ||
    '';

  const match = sourceUrl.match(
    /\/(?:p|reel|tv)\/([^/?]+)/i
  );

  const sourceId =
    post.source_id ||
    (match ? match[1] : null);

  return {
    json: {
      ...post,
      source_url: sourceUrl,
      source_id: sourceId
    }
  };
});

const inputItems = $input.all();
const originalPosts = $('Extract Instagram Post Data').all();

function extractJsonArray(text, key) {
  const marker = `"${key}":`;
  const start = text.indexOf(marker);

  if (start === -1) return [];

  let i = start + marker.length;

  while (i < text.length && /\s/.test(text[i])) {
    i++;
  }

  if (text[i] !== '[') return [];

  const arrayStart = i;
  let depth = 0;
  let inString = false;
  let escaped = false;

  for (; i < text.length; i++) {
    const char = text[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === '\\') {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === '[') {
      depth++;
    } else if (char === ']') {
      depth--;

      if (depth === 0) {
        try {
          return JSON.parse(text.slice(arrayStart, i + 1));
        } catch {
          return [];
        }
      }
    }
  }

  return [];
}

function decodeUrl(url) {
  if (!url) return null;

  let decoded = String(url)
    .replace(/\\\//g, '/')
    .replace(/\\u0025/g, '%')
    .replace(/\\u0026/g, '&')
    .replace(/&amp;/gi, '&');

  try {
    decoded = decodeURIComponent(decoded);
  } catch {
    // Keep original value
  }

  return decoded.trim();
}


// =====================================
// Process ALL Instagram posts
// =====================================

const output = [];

for (let i = 0; i < inputItems.length; i++) {

  const html = inputItems[i]?.json?.data || '';
  const originalPost = originalPosts[i]?.json || {};

  // -----------------------------------
  // Profile information
  // -----------------------------------

  const username =
    html.match(/"username":"([^"]+)"/)?.[1] ||
    originalPost.instagram_username ||
    null;

  const fullName =
    html.match(/"full_name":"([^"]+)"/)?.[1] ||
    null;

  const biographyMatch =
    html.match(/"biography":"([\s\S]*?)","full_name"/);

  let biography = null;

  if (biographyMatch) {
    try {
      biography = JSON.parse(`"${biographyMatch[1]}"`);
    } catch {
      biography = biographyMatch[1];
    }
  }


  // -----------------------------------
  // Instagram IDs
  // -----------------------------------

  const profileId =
    html.match(/"id":"(\d+)","lox_highlights_connection"/)?.[1] ||
    null;

  const profilePk =
    html.match(/"pk":"(\d+)","username":"[^"]+","id":"\d+"/)?.[1] ||
    null;


  // -----------------------------------
  // Extract ALL bio links
  // -----------------------------------

  let bioLinks = [];

  try {
    bioLinks = extractJsonArray(html, 'bio_links');
  } catch {
    bioLinks = [];
  }


  // -----------------------------------
  // Clean links
  // -----------------------------------

  const links = bioLinks
    .map(link => ({
      title: link.title || null,
      url: decodeUrl(link.url),
      link_type: link.link_type || null,
      link_id: link.link_id || null
    }))
    .filter(link => link.url);


  // -----------------------------------
  // Common original post data
  // -----------------------------------

  const commonData = {
    instagram_username: username,

    instagram_profile_url:
      `https://www.instagram.com/${username}/`,

    full_name: fullName,
    biography: biography,

    profile_id: profileId,
    profile_pk: profilePk,

    // Original Instagram POST
    caption: originalPost.caption || null,
    image_url: originalPost.image_url || null,
    permalink: originalPost.permalink || null,
    timestamp: originalPost.timestamp || null
  };


  // -----------------------------------
  // FINAL OUTPUT
  // ONE ITEM PER INSTAGRAM POST
  // ALL BIO LINKS AS ARRAY
  // -----------------------------------

  output.push({
    json: {
      ...commonData,

      bio_links: links
    }
  });
}


// =====================================
// Final output
// =====================================

return output;

const responses = $input.all();

const bioItems = $('Expand Bio Links').all();
const originalBioItems = $('IF - Has Bio Link').all();
const postItems = $('Extract Instagram Post Data').all();


// =====================================
// Clean URL
// =====================================

function cleanUrl(value) {
  if (!value) return null;

  return String(value)
    .replace(/\\\//g, '/')
    .replace(/\\u0025/g, '%')
    .replace(/\\u0026/g, '&')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .trim();
}


// =====================================
// Check ticket-related URL/title
// =====================================

function isTicketUrl(value) {
  if (!value) return false;

  const text = String(value).toLowerCase();

  return (
    /ticket|tickets|buyticket|buy-tickets/.test(text) ||
    /eventbrite/.test(text) ||
    /tickettailor/.test(text) ||
    /ticketmaster/.test(text) ||
    /weeztix/.test(text) ||
    /eventix/.test(text) ||
    /buytickets\.at/.test(text)
  );
}


// =====================================
// Store ticket URL per Instagram account
// =====================================

const accountTickets = new Map();


// =====================================
// STEP 1
// Read every Split Out bio link
// =====================================

for (let i = 0; i < bioItems.length; i++) {

  const bio = bioItems[i]?.json || {};

  // Since Split Out has No Other Fields,
  // get username from original IF item.
  const originalBio =
    originalBioItems[0]?.json || {};

  const username =
    originalBio.instagram_username || null;

  if (!username) continue;

  if (!accountTickets.has(username)) {
    accountTickets.set(username, null);
  }

  const bioUrl = cleanUrl(bio.url);
  const bioTitle = bio.title || '';

  // -----------------------------------
  // Direct ticket link
  // -----------------------------------

  if (
    !accountTickets.get(username) &&
    bioUrl &&
    (
      isTicketUrl(bioUrl) ||
      isTicketUrl(bioTitle)
    )
  ) {
    accountTickets.set(username, bioUrl);
  }
}


// =====================================
// STEP 2
// Check fetched HTML
// =====================================

for (let i = 0; i < responses.length; i++) {

  const response = responses[i]?.json || {};
  const bio = bioItems[i]?.json || {};

  const originalBio =
    originalBioItems[0]?.json || {};

  const username =
    originalBio.instagram_username || null;

  if (!username) continue;

  // Direct ticket URL already found
  if (accountTickets.get(username)) {
    continue;
  }

  const html = response.data || '';

  if (!html) continue;


  // -----------------------------------
  // Extract links from HTML
  // -----------------------------------

  const matches = [
    ...html.matchAll(
      /<a\b[^>]*href\s*=\s*["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi
    )
  ];


  // -----------------------------------
  // Find ticket link
  // -----------------------------------

  for (const match of matches) {

    const href = cleanUrl(match[1]);

    if (!href) continue;

    const text = String(match[2] || '')
      .replace(/<[^>]*>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    if (
      isTicketUrl(href) ||
      isTicketUrl(text)
    ) {
      accountTickets.set(username, href);
      break;
    }
  }
}


// =====================================
// STEP 3
// Return ONE ITEM per Instagram POST
// =====================================

return postItems.map(post => {

  const data = post.json || {};

  const username =
    data.instagram_username || null;

  return {
    json: {
      ...data,

      ticket_url:
        accountTickets.get(username) || null
    }
  };
});
